```python
import re
import uuid
from datetime import datetime, timezone

ALLOWED_CONTENT_TYPES = ("image/jpeg", "image/png")
MAX_UPLOAD_BYTES = 5 * 1024 * 1024
MAX_PRESIGN_SECONDS = 3600
_UNSAFE_CHARS = re.compile(r"[^A-Za-z0-9._-]")
_PHOTO_COLUMNS = ("id", "title", "description", "s3_key", "uploaded_at")


def init_db(conn) -> None:
    cur = conn.cursor()
    cur.execute(
        """
        CREATE TABLE IF NOT EXISTS photos (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            title TEXT NOT NULL,
            description TEXT,
            s3_key TEXT NOT NULL,
            uploaded_at TEXT NOT NULL
        )
        """
    )
    conn.commit()


def save_photo_metadata(conn, title, description, s3_key) -> int:
    uploaded_at = datetime.now(timezone.utc).isoformat()
    cur = conn.cursor()
    cur.execute(
        "INSERT INTO photos (title, description, s3_key, uploaded_at) "
        "VALUES (?, ?, ?, ?)",
        (title, description, s3_key, uploaded_at),
    )
    new_id = cur.lastrowid
    conn.commit()
    return int(new_id)


def _escape_like(term: str) -> str:
    return (
        term.replace("\\", "\\\\")
        .replace("%", "\\%")
        .replace("_", "\\_")
    )


def search_photos(conn, term) -> list:
    pattern = "%" + _escape_like(str(term)) + "%"
    cur = conn.cursor()
    cur.execute(
        "SELECT id, title, description, s3_key, uploaded_at FROM photos "
        "WHERE title LIKE ? ESCAPE '\\' OR description LIKE ? ESCAPE '\\' "
        "ORDER BY id ASC",
        (pattern, pattern),
    )
    rows = cur.fetchall()
    return [dict(zip(_PHOTO_COLUMNS, row)) for row in rows]


def _safe_name(filename: str) -> str:
    # Strip any directory components (both separator styles).
    base = str(filename).replace("\\", "/").rsplit("/", 1)[-1]
    safe = _UNSAFE_CHARS.sub("_", base)
    if safe in ("", ".", ".."):
        raise ValueError("invalid filename")
    return safe


def upload_photo(s3, bucket, filename, data, content_type) -> str:
    if content_type not in ALLOWED_CONTENT_TYPES:
        raise ValueError("unsupported content type")
    if len(data) > MAX_UPLOAD_BYTES:
        raise ValueError("photo exceeds 5 MiB limit")
    safe = _safe_name(filename)
    key = "photos/" + uuid.uuid4().hex + "/" + safe
    s3.put_object(Bucket=bucket, Key=key, Body=data, ContentType=content_type)
    return key


def photo_url(s3, bucket, key, expires=3600) -> str:
    if (
        not isinstance(expires, int)
        or isinstance(expires, bool)
        or not (1 <= expires <= MAX_PRESIGN_SECONDS)
    ):
        raise ValueError("expires must be between 1 and 3600 seconds")
    return s3.generate_presigned_url(
        "get_object",
        Params={"Bucket": bucket, "Key": key},
        ExpiresIn=expires,
    )


def handle_upload(conn, s3, bucket, title, description, filename, data, content_type) -> int:
    key = upload_photo(s3, bucket, filename, data, content_type)
    try:
        return save_photo_metadata(conn, title, description, key)
    except Exception:
        try:
            s3.delete_object(Bucket=bucket, Key=key)
        except Exception:
            pass  # Preserve the original metadata-save failure.
        raise
